package Collections_Framework.Queue;import java.util.*;public class QUEUE_LINKEDLIST {    public static void main(String[] args) {        Queue<Integer> q = new LinkedList<>(); {         q.offer(1);         q.offer(2);         q.offer(3);         q.offer(4);         System.out.println(q);         System.out.println(q.poll());         q.offer(1);         System.out.println(q);        }    }}//offer is used to add elements in queue//poll is used to delete elements in queue in FIFO order(mtlb jo oldest insert hoga woh delete hoga)